export const TEMPLATES: Record<string, string> = {
  ".dockerignore": "node_modules\ndist\ndata\n.git\n.env\n*.local\n",
  ".gitignore": "node_modules\ndist\ndata\n.env\n*.local\n.tanstack\n",
  ".mcp.json": "{\n  \"mcpServers\": {\n    \"smithable\": { \"command\": \"smithable\", \"args\": [\"mcp\"] }\n  }\n}\n",
  "AGENTS.md": "# Working on this app\n\nThis app is generated by [Smithable](https://smithable.ax) from `smithable.yml` (what it does), `smithable.auth.yml` (sign-in, roles, access) and `smithable.content.yml` (visible text). The code follows the usual TanStack Start, Drizzle and shadcn/ui idioms, but most of it is regenerated on every change.\n\n## Change the app through Smithable, not by editing files\n\n- **With MCP** (`.mcp.json` registers `smithable mcp`): call `smithable_context` with the request to see the parts of the app it is about, then an operation tool such as `smithable_add_field`. Each operation checks the change, regenerates the code, migrates the database and commits a checkpoint; `smithable_undo` reverts it. `smithable_inspect` shows any concept with its files and tests.\n- **Without MCP:** `smithable context \"<request>\"`, `smithable op <operation> …` (`smithable op` lists them), `smithable inspect <concept>`, `smithable undo`.\n- You rarely need to read the source to make a change.\n- When no operation can make a page look or behave as asked, `smithable_customize_page` (or `smithable customize page:<page>`) gives it its own component in `src/custom/pages/`, starting as a copy of the generated one. Edit that file, never the generated route.\n\n## Who owns which files\n\n| Path | Owner | |\n|---|---|---|\n| `smithable*.yml` | The project | Changed through operations |\n| `src/generated/`, `src/db/schema.ts`, `src/db/seed.ts`, generated routes, `src/lib/auth.ts` | Smithable | Overwritten on every change: never edit |\n| `src/kit/`, `src/components/ui/` | Smithable | Updated with Smithable: never edit; copy into `src/custom/` to change |\n| `src/custom/` | You | Never touched by Smithable |\n| `drizzle/` | History | Migrations; never edit old ones |\n\n## Custom code\n\n- A custom action's implementation is `src/custom/actions/<action>.ts`. Its input and output types come from the spec.\n- Read and write data with the functions in `src/generated/<model>.server.ts`: they apply the access rules. The signed-in user is `await currentViewer()` from `#/lib/viewer.server`.\n- Mark code that implements a rule with `// implements rule <id>`, and its test with `test(\"rule <id>: …\")`, then run `smithable test`: `smithable inspect` shows each rule's status.\n",
  "CLAUDE.md": "@AGENTS.md\n",
  "Dockerfile": "# Builds the app into a small image. Irreplaceable state lives in the /data volume.\nFROM node:24-slim AS build\nWORKDIR /app\nRUN corepack enable\nCOPY package.json pnpm-lock.yaml pnpm-workspace.yaml ./\nRUN pnpm install --frozen-lockfile\nCOPY . .\nRUN pnpm build && pnpm prune --prod && mkdir -p /data\n\n# A minimal runtime (Node and little else, no shell), as a user without root rights: fewer\n# packages means fewer vulnerabilities to patch (smithable security --level release checks it).\nFROM gcr.io/distroless/nodejs24-debian13:nonroot\nWORKDIR /app\nENV NODE_ENV=production PORT=3000 DATA_DIR=/data\nCOPY --from=build /app/package.json ./\nCOPY --from=build /app/node_modules ./node_modules\nCOPY --from=build /app/dist ./dist\nCOPY --from=build /app/drizzle ./drizzle\nCOPY --from=build /app/server.mjs ./\nCOPY --from=build --chown=nonroot:nonroot /data /data\nVOLUME /data\nEXPOSE 3000\nHEALTHCHECK CMD [\"/nodejs/bin/node\", \"-e\", \"fetch('http://localhost:' + process.env.PORT + '/health').then((r) => process.exit(r.ok ? 0 : 1), () => process.exit(1))\"]\nCMD [\"server.mjs\"]\n",
  "drizzle.config.ts": "import { defineConfig } from \"drizzle-kit\";\n\nexport default defineConfig({\n  dialect: \"sqlite\",\n  schema: \"./src/db/schema.ts\",\n  out: \"./drizzle\",\n  casing: \"snake_case\",\n  dbCredentials: { url: `${process.env.DATA_DIR ?? \"data\"}/db/app.db` },\n});\n",
  "playwright.config.ts": "import { rmSync } from \"node:fs\";\nimport { defineConfig, devices } from \"@playwright/test\";\n\n// The smoke tests run the app on port 3100 (or SMOKE_PORT) with their own, empty database.\nrmSync(\"data/smoke\", { recursive: true, force: true });\nconst port = Number(process.env.SMOKE_PORT ?? 3100);\n\nexport default defineConfig({\n  testDir: \"tests\",\n  fullyParallel: false,\n  workers: 1,\n  reporter: \"list\",\n  use: { baseURL: `http://localhost:${port}` },\n  projects: [{ name: \"chromium\", use: { ...devices[\"Desktop Chrome\"] } }],\n  webServer: {\n    // Vite itself, not through pnpm, so it stops when the tests end.\n    command: `vite dev --port ${port} --strictPort`,\n    url: `http://localhost:${port}/health`,\n    env: { DATA_DIR: \"data/smoke\" },\n    reuseExistingServer: false,\n    timeout: 120_000,\n  },\n});\n",
  "pnpm-workspace.yaml": "allowBuilds:\n  better-sqlite3: true\n  esbuild: true\n",
  "server.mjs": "// Smithable app kit: the production server (`pnpm start`, and the container). It serves the\n// built files and the app, and gives every response the security headers; pages also get a\n// Content Security Policy from the root route (src/kit/security.ts).\nimport { serve } from \"srvx\";\nimport { staticMiddleware } from \"srvx/static\";\nimport app from \"./dist/server/server.js\";\n\nconst HEADERS = {\n  \"X-Content-Type-Options\": \"nosniff\",\n  \"X-Frame-Options\": \"DENY\",\n  \"Referrer-Policy\": \"strict-origin-when-cross-origin\",\n  \"Permissions-Policy\": \"camera=(), microphone=(), geolocation=(), payment=(), usb=()\",\n  \"Cross-Origin-Opener-Policy\": \"same-origin\",\n  \"Cross-Origin-Resource-Policy\": \"same-origin\",\n  \"Cross-Origin-Embedder-Policy\": \"require-corp\",\n};\n\nserve({\n  port: Number(process.env.PORT ?? 3000),\n  gracefulShutdown: true,\n  fetch: app.fetch,\n  middleware: [\n    async (_request, next) => {\n      const response = await next();\n      for (const [name, value] of Object.entries(HEADERS))\n        if (!response.headers.has(name)) response.headers.set(name, value);\n      return response;\n    },\n    staticMiddleware({ dir: new URL(\"./dist/client\", import.meta.url).pathname }),\n  ],\n});\n",
  "src/components/ui/badge.tsx": "import { cva, type VariantProps } from \"class-variance-authority\";\nimport type * as React from \"react\";\nimport { cn } from \"#/lib/utils\";\n\nconst badgeVariants = cva(\n  \"inline-flex items-center rounded-md px-2 py-0.5 text-xs font-semibold whitespace-nowrap\",\n  {\n    variants: {\n      variant: {\n        default: \"bg-accent text-accent-foreground\",\n        success: \"bg-success text-success-foreground\",\n        warning: \"bg-warning text-warning-foreground\",\n        danger: \"bg-destructive text-destructive-foreground\",\n      },\n    },\n    defaultVariants: { variant: \"default\" },\n  },\n);\n\nexport function Badge({\n  className,\n  variant,\n  ...props\n}: React.ComponentProps<\"span\"> & VariantProps<typeof badgeVariants>) {\n  return <span className={cn(badgeVariants({ variant, className }))} {...props} />;\n}\n",
  "src/components/ui/button.tsx": "import { cva, type VariantProps } from \"class-variance-authority\";\nimport type * as React from \"react\";\nimport { cn } from \"#/lib/utils\";\n\nconst buttonVariants = cva(\n  \"inline-flex shrink-0 cursor-pointer items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-semibold transition-colors outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background active:inset-ring-2 active:inset-ring-foreground/20 disabled:pointer-events-none disabled:border-transparent disabled:bg-muted disabled:text-muted-foreground disabled:shadow-none [&_svg]:pointer-events-none [&_svg]:size-5 [&_svg]:shrink-0\",\n  {\n    variants: {\n      variant: {\n        default: \"bg-primary text-primary-foreground hover:bg-primary/90\",\n        destructive: \"bg-destructive text-destructive-foreground hover:bg-destructive/90\",\n        outline: \"border border-input bg-card hover:bg-accent hover:text-accent-foreground\",\n        secondary: \"bg-secondary text-secondary-foreground hover:bg-secondary/80\",\n        ghost: \"hover:bg-accent hover:text-accent-foreground\",\n      },\n      size: {\n        default: \"h-control px-4\",\n        sm: \"h-9 px-3 pointer-coarse:h-11\",\n        icon: \"size-control\",\n      },\n    },\n    defaultVariants: { variant: \"default\", size: \"default\" },\n  },\n);\n\nexport function Button({\n  className,\n  variant,\n  size,\n  ...props\n}: React.ComponentProps<\"button\"> & VariantProps<typeof buttonVariants>) {\n  return <button className={cn(buttonVariants({ variant, size, className }))} {...props} />;\n}\n\nexport { buttonVariants };\n",
  "src/components/ui/card.tsx": "import type * as React from \"react\";\nimport { cn } from \"#/lib/utils\";\n\nexport function Card({ className, ...props }: React.ComponentProps<\"div\">) {\n  return (\n    <div\n      className={cn(\"rounded-lg border bg-card text-card-foreground shadow-card\", className)}\n      {...props}\n    />\n  );\n}\n",
  "src/components/ui/input.tsx": "import type * as React from \"react\";\nimport { cn } from \"#/lib/utils\";\n\n// 16 px text on phones, so browsers do not zoom into a field being edited.\nexport const fieldClassName =\n  \"w-full min-w-0 rounded-md border border-input bg-card px-3 text-base text-foreground outline-none transition-[color,box-shadow] placeholder:text-muted-foreground hover:border-foreground/40 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:bg-muted disabled:text-muted-foreground aria-invalid:border-destructive aria-invalid:border-2 md:text-sm\";\n\nexport function Input({ className, ...props }: React.ComponentProps<\"input\">) {\n  return <input className={cn(fieldClassName, \"h-control\", className)} {...props} />;\n}\n\nexport function Textarea({ className, ...props }: React.ComponentProps<\"textarea\">) {\n  return <textarea className={cn(fieldClassName, \"min-h-24 py-2\", className)} {...props} />;\n}\n\nexport function NativeSelect({ className, ...props }: React.ComponentProps<\"select\">) {\n  return <select className={cn(fieldClassName, \"h-control pr-8\", className)} {...props} />;\n}\n\nexport function Checkbox({ className, ...props }: React.ComponentProps<\"input\">) {\n  return (\n    <input\n      type=\"checkbox\"\n      className={cn(\n        \"size-5 rounded accent-primary outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background\",\n        className,\n      )}\n      {...props}\n    />\n  );\n}\n\nexport function Label({\n  className,\n  htmlFor,\n  children,\n  ...props\n}: React.ComponentProps<\"label\"> & { htmlFor: string }) {\n  return (\n    <label\n      htmlFor={htmlFor}\n      className={cn(\"text-sm font-semibold leading-5\", className)}\n      {...props}\n    >\n      {children}\n    </label>\n  );\n}\n",
  "src/components/ui/table.tsx": "import type * as React from \"react\";\nimport { cn } from \"#/lib/utils\";\n\nexport function Table({ className, ...props }: React.ComponentProps<\"table\">) {\n  return (\n    <div className=\"relative w-full overflow-x-auto\">\n      <table className={cn(\"w-full caption-bottom text-sm\", className)} {...props} />\n    </div>\n  );\n}\n\nexport function TableHeader({ className, ...props }: React.ComponentProps<\"thead\">) {\n  return <thead className={cn(\"bg-muted [&_tr]:border-b\", className)} {...props} />;\n}\n\nexport function TableBody({ className, ...props }: React.ComponentProps<\"tbody\">) {\n  return <tbody className={cn(\"[&_tr:last-child]:border-0\", className)} {...props} />;\n}\n\nexport function TableRow({ className, ...props }: React.ComponentProps<\"tr\">) {\n  return <tr className={cn(\"border-b transition-colors hover:bg-accent\", className)} {...props} />;\n}\n\nexport function TableHead({ className, ...props }: React.ComponentProps<\"th\">) {\n  return (\n    <th\n      className={cn(\n        \"h-11 px-cell text-left align-middle text-[11px] leading-4 font-semibold uppercase tracking-wide text-muted-foreground\",\n        className,\n      )}\n      {...props}\n    />\n  );\n}\n\nexport function TableCell({ className, ...props }: React.ComponentProps<\"td\">) {\n  return <td className={cn(\"h-row px-cell py-2 align-middle\", className)} {...props} />;\n}\n",
  "src/db/index.ts": "// Smithable app kit: opens the SQLite database under DATA_DIR and applies pending migrations.\nimport { mkdirSync } from \"node:fs\";\nimport { join } from \"node:path\";\nimport Database from \"better-sqlite3\";\nimport { drizzle } from \"drizzle-orm/better-sqlite3\";\nimport { migrate } from \"drizzle-orm/better-sqlite3/migrator\";\nimport * as schema from \"./schema\";\n\nconst dataDir = process.env.DATA_DIR ?? \"data\";\nmkdirSync(join(dataDir, \"db\"), { recursive: true });\n\nconst sqlite = new Database(join(dataDir, \"db\", \"app.db\"));\nsqlite.pragma(\"journal_mode = WAL\");\nsqlite.pragma(\"foreign_keys = ON\");\n\nexport const db = drizzle(sqlite, { schema, casing: \"snake_case\" });\n\n// Some changes rebuild a table (e.g. making a column required). SQLite only lets a migration do\n// that with foreign keys off, and ignores switching them off inside the migration's transaction;\n// so they are off around it, and every reference is checked afterwards.\nsqlite.pragma(\"foreign_keys = OFF\");\ntry {\n  migrate(db, { migrationsFolder: \"drizzle\" });\n  const broken = sqlite.pragma(\"foreign_key_check\") as unknown[];\n  if (broken.length > 0) throw new Error(`A migration left ${broken.length} broken references.`);\n} finally {\n  sqlite.pragma(\"foreign_keys = ON\");\n}\n",
  "src/kit/AppShell.tsx": "// Smithable app kit: the application frame with navigation menus and the signed-in user.\nimport { Link, type LinkProps } from \"@tanstack/react-router\";\nimport { LogOut, type LucideIcon, Menu, X } from \"lucide-react\";\nimport { useRef } from \"react\";\nimport { allows, type Rule, type Viewer } from \"./access\";\nimport { textMarker } from \"./model\";\n\nexport interface MenuUi {\n  name: string;\n  label?: string;\n  /** Only pages the viewer may open are shown. */\n  items: { to: LinkProps[\"to\"]; label: string; icon?: LucideIcon; access: Rule }[];\n}\n\ninterface ShellProps {\n  appName: string;\n  menus: MenuUi[];\n  viewer: Viewer | null;\n  /** Without it the app has no sign-in. */\n  onSignOut?: () => Promise<void>;\n}\n\n// Links and buttons on the sidebar's own colours, with 44 px targets.\nconst sidebarItem =\n  \"flex min-h-11 items-center gap-3 rounded-md px-3 text-sm font-medium transition-colors hover:bg-accent hover:text-accent-foreground outline-none focus-visible:ring-2 focus-visible:ring-sidebar-foreground\";\n\nexport function AppShell({ children, ...shell }: ShellProps & { children: React.ReactNode }) {\n  const drawer = useRef<HTMLDialogElement>(null);\n  return (\n    <div className=\"min-h-screen lg:flex\">\n      {/* Desktop: a sidebar. */}\n      <aside className=\"hidden border-r bg-sidebar text-sidebar-foreground lg:sticky lg:top-0 lg:flex lg:h-screen lg:w-56 lg:shrink-0 lg:flex-col\">\n        <p className=\"px-6 pt-7 pb-6 text-2xl font-bold\">{shell.appName}</p>\n        <Navigation {...shell} />\n      </aside>\n      {/* Phones and tablets: a header whose menu opens the same navigation as a drawer. */}\n      <header className=\"sticky top-0 z-10 flex h-18 items-center gap-2 border-b bg-sidebar px-2 text-sidebar-foreground lg:hidden\">\n        <button\n          type=\"button\"\n          aria-label=\"Open menu\"\n          className={`${sidebarItem} size-11 justify-center px-0`}\n          onClick={() => drawer.current?.showModal()}\n        >\n          <Menu aria-hidden className=\"size-6\" />\n        </button>\n        <p className=\"min-w-0 truncate text-lg font-bold\">{shell.appName}</p>\n      </header>\n      <dialog\n        ref={drawer}\n        aria-label=\"Menu\"\n        className=\"m-0 h-dvh max-h-none w-72 max-w-[85vw] flex-col bg-sidebar text-sidebar-foreground backdrop:bg-black/50 open:flex lg:hidden\"\n      >\n        <div className=\"flex h-18 shrink-0 items-center justify-between gap-2 pr-2 pl-5\">\n          <p className=\"min-w-0 truncate text-lg font-bold\">{shell.appName}</p>\n          <button\n            type=\"button\"\n            aria-label=\"Close menu\"\n            className={`${sidebarItem} size-11 justify-center px-0`}\n            onClick={() => drawer.current?.close()}\n          >\n            <X aria-hidden className=\"size-6\" />\n          </button>\n        </div>\n        <Navigation {...shell} onNavigate={() => drawer.current?.close()} />\n      </dialog>\n      <main className=\"min-w-0 flex-1 px-5 py-6 lg:px-9 lg:py-8\">{children}</main>\n    </div>\n  );\n}\n\nfunction Navigation({\n  menus,\n  viewer,\n  onSignOut,\n  onNavigate,\n}: ShellProps & { onNavigate?: () => void }) {\n  return (\n    <>\n      <nav aria-label=\"Main\" className=\"flex flex-1 flex-col gap-5 overflow-y-auto px-3 pb-4\">\n        {menus.map((menu) => {\n          const items = menu.items.filter((item) => allows(item.access, viewer));\n          if (items.length === 0) return null;\n          return (\n            <div key={menu.name} className=\"flex flex-col gap-1\">\n              {menu.label && (\n                <p className=\"px-3 pb-1 text-xs font-semibold uppercase tracking-wide\">\n                  {menu.label}\n                </p>\n              )}\n              {items.map((item) => (\n                <Link\n                  key={String(item.to)}\n                  to={item.to}\n                  onClick={onNavigate}\n                  className={sidebarItem}\n                  activeProps={{\n                    className:\n                      \"bg-primary font-semibold text-primary-foreground hover:bg-primary hover:text-primary-foreground\",\n                  }}\n                >\n                  {item.icon && <item.icon aria-hidden className=\"size-5 shrink-0\" />}\n                  {item.label}\n                </Link>\n              ))}\n            </div>\n          );\n        })}\n      </nav>\n      {onSignOut && (\n        <div className=\"mx-3 border-t border-sidebar-foreground/30 px-3 py-4 text-sm\">\n          {viewer ? (\n            <>\n              <p className=\"truncate font-semibold\" title={viewer.email}>\n                {viewer.name}\n              </p>\n              <p className=\"capitalize\">{viewer.role}</p>\n              <button type=\"button\" onClick={onSignOut} className={`${sidebarItem} -mx-3 mt-2`}>\n                <LogOut aria-hidden className=\"size-5\" />\n                Sign out\n              </button>\n            </>\n          ) : (\n            <a href=\"/sign-in\" className={`${sidebarItem} -mx-3`}>\n              Sign in\n            </a>\n          )}\n        </div>\n      )}\n    </>\n  );\n}\n\n/** Shown instead of a page that failed, e.g. \"You are not allowed to do this.\" */\nexport function ErrorNotice({ title, message }: { title: string; message?: string }) {\n  return (\n    <div className=\"max-w-xl\">\n      <PageHeader title={title} />\n      {message && <p className=\"text-muted-foreground\">{message}</p>}\n    </div>\n  );\n}\n\nexport function PageHeader({\n  title,\n  subtitle,\n  actions,\n  page,\n}: {\n  title: string;\n  subtitle?: string;\n  actions?: React.ReactNode;\n  /** The page's name in the spec: its texts can then be changed in the preview. */\n  page?: string;\n}) {\n  return (\n    <div className=\"mb-6 flex flex-col gap-4 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between\">\n      <div className=\"min-w-0\">\n        <h1\n          className=\"break-words text-[28px] leading-9 font-bold lg:text-[32px] lg:leading-10\"\n          {...(page ? textMarker(`pages.${page}.title`) : {})}\n        >\n          {title}\n        </h1>\n        {subtitle && (\n          <p\n            className=\"mt-1 text-muted-foreground\"\n            {...(page ? textMarker(`pages.${page}.subtitle`) : {})}\n          >\n            {subtitle}\n          </p>\n        )}\n      </div>\n      {actions && (\n        <div className=\"flex flex-wrap items-center gap-2 max-sm:[&>*]:flex-1\">{actions}</div>\n      )}\n    </div>\n  );\n}\n",
  "src/kit/Combobox.tsx": "// Smithable app kit: a searchable choice of a related record (the WAI-ARIA combobox pattern).\n// Type to filter, arrow keys to move, Enter to choose, Escape to close.\nimport { ChevronDown, X } from \"lucide-react\";\nimport { useId, useState } from \"react\";\nimport { fieldClassName } from \"#/components/ui/input\";\nimport { cn } from \"#/lib/utils\";\n\ninterface ComboboxProps {\n  id: string;\n  /** The chosen record's id as text, or \"\" for none. */\n  value: string;\n  options: { value: string | number; label: string }[];\n  required: boolean;\n  invalid: boolean;\n  describedBy?: string;\n  onChange: (value: string) => void;\n}\n\nexport function Combobox({\n  id,\n  value,\n  options,\n  required,\n  invalid,\n  describedBy,\n  onChange,\n}: ComboboxProps) {\n  const list = useId();\n  const labelOf = (v: string) => options.find((o) => String(o.value) === v)?.label ?? \"\";\n  const [text, setText] = useState(() => labelOf(value));\n  const [open, setOpen] = useState(false);\n  const [active, setActive] = useState(0);\n  const typed = text !== labelOf(value);\n  const shown = typed\n    ? options.filter((o) => o.label.toLowerCase().includes(text.trim().toLowerCase()))\n    : options;\n\n  const choose = (v: string) => {\n    onChange(v);\n    setText(labelOf(v));\n    setOpen(false);\n  };\n  const close = () => {\n    setOpen(false);\n    // Leaving the field: empty text clears an optional choice; otherwise the choice stays.\n    if (text.trim() === \"\" && !required) choose(\"\");\n    else setText(labelOf(value));\n  };\n  const onKeyDown = (event: React.KeyboardEvent) => {\n    if (event.key === \"ArrowDown\" || event.key === \"ArrowUp\") {\n      event.preventDefault();\n      if (!open) setOpen(true);\n      const step = event.key === \"ArrowDown\" ? 1 : -1;\n      setActive((i) => (shown.length ? (i + step + shown.length) % shown.length : 0));\n    } else if (event.key === \"Enter\" && open) {\n      event.preventDefault();\n      const option = shown[active];\n      if (option) choose(String(option.value));\n    } else if (event.key === \"Escape\" && open) {\n      event.preventDefault();\n      setOpen(false);\n      setText(labelOf(value));\n    }\n  };\n\n  return (\n    <div className=\"relative\">\n      <input\n        id={id}\n        role=\"combobox\"\n        aria-expanded={open}\n        aria-controls={list}\n        aria-autocomplete=\"list\"\n        aria-activedescendant={open && shown[active] ? `${list}-${active}` : undefined}\n        aria-invalid={invalid || undefined}\n        aria-describedby={describedBy}\n        autoComplete=\"off\"\n        placeholder=\"Search…\"\n        className={cn(fieldClassName, \"h-control pr-18\")}\n        value={text}\n        onChange={(e) => {\n          setText(e.target.value);\n          setActive(0);\n          setOpen(true);\n        }}\n        onFocus={() => setOpen(true)}\n        onBlur={close}\n        onKeyDown={onKeyDown}\n      />\n      <div className=\"absolute inset-y-0 right-1 flex items-center\">\n        {value && !required && (\n          <button\n            type=\"button\"\n            aria-label=\"Clear\"\n            className=\"flex size-9 cursor-pointer items-center justify-center rounded-md text-muted-foreground hover:text-foreground\"\n            onMouseDown={(e) => e.preventDefault()}\n            onClick={() => choose(\"\")}\n          >\n            <X aria-hidden className=\"size-4\" />\n          </button>\n        )}\n        <ChevronDown\n          aria-hidden\n          className=\"pointer-events-none mr-2 size-4 text-muted-foreground\"\n        />\n      </div>\n      {open && (\n        <div className=\"absolute z-20 mt-1 max-h-64 w-full overflow-y-auto rounded-md border bg-card py-1 shadow-lg\">\n          <div id={list} role=\"listbox\" aria-label=\"Options\">\n            {shown.map((option, i) => (\n              <div\n                key={option.value}\n                id={`${list}-${i}`}\n                role=\"option\"\n                tabIndex={-1}\n                aria-selected={String(option.value) === value}\n                className={cn(\n                  \"cursor-pointer px-3 py-2 text-sm aria-selected:font-semibold\",\n                  i === active && \"bg-accent text-accent-foreground\",\n                )}\n                onMouseDown={(e) => {\n                  e.preventDefault();\n                  choose(String(option.value));\n                }}\n              >\n                {option.label}\n              </div>\n            ))}\n          </div>\n          {shown.length === 0 && (\n            <p className=\"px-3 py-2 text-sm text-muted-foreground\">\n              {options.length\n                ? `Nothing matches “${text.trim()}”.`\n                : \"There is nothing to choose yet.\"}\n            </p>\n          )}\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "src/kit/Dashboard.tsx": "// Smithable app kit: dashboard tiles. A number, and a bar chart with one bar per month.\n// To change one, copy this file into src/custom/components/ and edit the copy.\nimport { Card } from \"#/components/ui/card\";\nimport type { AppUi } from \"./model\";\n\ntype Kind = \"money\" | \"int\" | \"decimal\";\n\n/** A number as the app shows it: money in the app's currency (stored in cents). */\nexport function formatNumber(\n  kind: Kind,\n  value: number | null,\n  app: AppUi,\n  compact = false,\n): string {\n  if (value === null) return \"—\";\n  const options: Intl.NumberFormatOptions = compact ? { notation: \"compact\" } : {};\n  if (kind === \"money\")\n    return new Intl.NumberFormat(undefined, {\n      ...options,\n      style: \"currency\",\n      currency: app.currency,\n    }).format(value / 100);\n  return new Intl.NumberFormat(undefined, {\n    ...options,\n    maximumFractionDigits: kind === \"int\" ? 0 : 2,\n  }).format(value);\n}\n\nexport function StatCard({ label, value }: { label: string; value: string }) {\n  return (\n    <Card className=\"space-y-2 p-card\">\n      <h2 className=\"text-sm font-semibold text-muted-foreground\">{label}</h2>\n      <p className=\"text-3xl font-bold tabular-nums\">{value}</p>\n    </Card>\n  );\n}\n\n/** Bars with their values written on them, so the chart reads without a pointer or colour. */\nexport function BarChart({\n  label,\n  kind,\n  app,\n  bars,\n}: {\n  label: string;\n  kind: Kind;\n  app: AppUi;\n  bars: { month: string; value: number }[];\n}) {\n  const max = Math.max(...bars.map((b) => b.value), 1);\n  const month = new Intl.DateTimeFormat(undefined, { month: \"short\", timeZone: \"UTC\" });\n  return (\n    <Card className=\"p-card\">\n      <h2 className=\"font-semibold\">{label}</h2>\n      {bars.length === 0 ? (\n        <p className=\"mt-4 text-muted-foreground\">No activity in this period.</p>\n      ) : (\n        <ol className=\"mt-6 flex h-56 items-end gap-2 sm:gap-4\">\n          {bars.map((bar) => (\n            <li\n              key={bar.month}\n              className=\"flex h-full min-w-0 flex-1 flex-col items-center justify-end gap-1\"\n            >\n              <span className=\"text-xs font-semibold tabular-nums\">\n                {formatNumber(kind, bar.value, app, true)}\n              </span>\n              <span\n                aria-hidden\n                className=\"w-full max-w-16 rounded-t-md bg-chart-1\"\n                style={{ height: `${(bar.value / max) * 100}%` }}\n              />\n              <span className=\"text-xs text-muted-foreground\">\n                {month.format(new Date(`${bar.month}-01T00:00:00Z`))}\n              </span>\n            </li>\n          ))}\n        </ol>\n      )}\n    </Card>\n  );\n}\n",
  "src/kit/FieldInput.tsx": "// Smithable app kit: the input control for one field, chosen by its kind.\nimport { Checkbox, Input, NativeSelect, Textarea } from \"#/components/ui/input\";\nimport { Combobox } from \"./Combobox\";\nimport type { FieldUi, Options } from \"./model\";\n\ninterface FieldInputProps {\n  field: FieldUi;\n  id: string;\n  value: string | boolean;\n  invalid: boolean;\n  /** Ids of the field's help and error text. */\n  describedBy?: string;\n  /** Choices for reference fields. */\n  options?: Options;\n  onChange: (value: string | boolean) => void;\n}\n\nconst inputTypes: Partial<Record<FieldUi[\"kind\"], string>> = {\n  email: \"email\",\n  phone: \"tel\",\n  url: \"url\",\n  date: \"date\",\n  datetime: \"datetime-local\",\n};\n\nexport function FieldInput({\n  field,\n  id,\n  value,\n  invalid,\n  describedBy,\n  options,\n  onChange,\n}: FieldInputProps) {\n  const common = {\n    id,\n    name: field.name,\n    \"aria-invalid\": invalid || undefined,\n    \"aria-describedby\": describedBy,\n  };\n  if (field.kind === \"bool\") {\n    return (\n      <Checkbox {...common} checked={value === true} onChange={(e) => onChange(e.target.checked)} />\n    );\n  }\n  const text = typeof value === \"string\" ? value : \"\";\n  if (field.kind === \"text\") {\n    return <Textarea {...common} value={text} onChange={(e) => onChange(e.target.value)} />;\n  }\n  if (field.kind === \"relation\" || field.kind === \"user\") {\n    return (\n      <Combobox\n        id={id}\n        value={text}\n        options={options?.[field.name] ?? []}\n        required={field.required}\n        invalid={invalid}\n        describedBy={describedBy}\n        onChange={onChange}\n      />\n    );\n  }\n  if (field.kind === \"choice\") {\n    return (\n      <NativeSelect {...common} value={text} onChange={(e) => onChange(e.target.value)}>\n        {!field.required && <option value=\"\">—</option>}\n        {field.choices?.map((choice) => (\n          <option key={choice.value} value={choice.value}>\n            {choice.label}\n          </option>\n        ))}\n      </NativeSelect>\n    );\n  }\n  const numeric = field.kind === \"int\" || field.kind === \"decimal\" || field.kind === \"money\";\n  return (\n    <Input\n      {...common}\n      type={inputTypes[field.kind] ?? \"text\"}\n      inputMode={numeric ? (field.kind === \"int\" ? \"numeric\" : \"decimal\") : undefined}\n      value={text}\n      onChange={(e) => onChange(e.target.value)}\n    />\n  );\n}\n",
  "src/kit/Landing.tsx": "// Smithable app kit: a landing page's layout and sections. Each section takes its texts as\n// props, and the generated page composes them. To change one, copy this file into\n// src/custom/components/ and edit the copy.\nimport { Link, type LinkProps } from \"@tanstack/react-router\";\nimport { Check, ChevronDown } from \"lucide-react\";\nimport { buttonVariants } from \"#/components/ui/button\";\nimport { Card } from \"#/components/ui/card\";\nimport { cn } from \"#/lib/utils\";\nimport { textMarker } from \"./model\";\n\nexport interface LandingLink {\n  to: LinkProps[\"to\"];\n  label: string;\n}\n\n/** The page frame: the app's name, a link into the app, and the sections. */\nexport function LandingLayout({\n  appName,\n  link,\n  children,\n}: {\n  appName: string;\n  link?: LandingLink;\n  children: React.ReactNode;\n}) {\n  return (\n    <div className=\"flex min-h-screen flex-col\">\n      <header className=\"border-b bg-card\">\n        <div className=\"mx-auto flex h-18 max-w-6xl items-center justify-between gap-4 px-5\">\n          <p className=\"min-w-0 truncate text-xl font-bold\">{appName}</p>\n          {link && (\n            <Link to={link.to} className={buttonVariants({ variant: \"outline\" })}>\n              {link.label}\n            </Link>\n          )}\n        </div>\n      </header>\n      <main className=\"flex-1\">{children}</main>\n      <footer className=\"border-t\">\n        <p className=\"mx-auto max-w-6xl px-5 py-8 text-sm text-muted-foreground\">{appName}</p>\n      </footer>\n    </div>\n  );\n}\n\n/** Marks one of a section's texts with where it is kept, e.g. \"pages.home.hero.title\". */\nconst mark = (texts: string | undefined, key: string) =>\n  texts ? textMarker(`${texts}.${key}`) : {};\n\nfunction Section({\n  texts,\n  id,\n  title,\n  text,\n  children,\n}: {\n  id: string;\n  title?: string;\n  text?: string;\n  children: React.ReactNode;\n  texts?: string;\n}) {\n  return (\n    <section\n      aria-labelledby={title ? `${id}-title` : undefined}\n      className=\"mx-auto max-w-6xl px-5 py-16\"\n    >\n      {title && (\n        <h2 id={`${id}-title`} className=\"text-2xl font-bold sm:text-3xl\" {...mark(texts, \"title\")}>\n          {title}\n        </h2>\n      )}\n      {text && (\n        <p className=\"mt-3 max-w-2xl text-lg text-muted-foreground\" {...mark(texts, \"text\")}>\n          {text}\n        </p>\n      )}\n      <div className={title || text ? \"mt-10\" : undefined}>{children}</div>\n    </section>\n  );\n}\n\nexport function Hero({\n  texts,\n  title,\n  subtitle,\n  link,\n}: {\n  title: string;\n  subtitle?: string;\n  link?: LandingLink;\n  texts?: string;\n}) {\n  return (\n    <section className=\"mx-auto max-w-6xl px-5 py-20 sm:py-28\">\n      <h1\n        className=\"max-w-3xl text-4xl leading-tight font-bold sm:text-5xl\"\n        {...mark(texts, \"title\")}\n      >\n        {title}\n      </h1>\n      {subtitle && (\n        <p className=\"mt-6 max-w-2xl text-lg text-muted-foreground\" {...mark(texts, \"subtitle\")}>\n          {subtitle}\n        </p>\n      )}\n      {link && (\n        <Link to={link.to} className={cn(buttonVariants(), \"mt-10 h-12 px-6 text-base\")}>\n          <span {...mark(texts, \"button\")}>{link.label}</span>\n        </Link>\n      )}\n    </section>\n  );\n}\n\nexport function Features({\n  texts,\n  title,\n  text,\n  items,\n}: {\n  title?: string;\n  text?: string;\n  items: { title?: string; text?: string }[];\n  texts?: string;\n}) {\n  return (\n    <Section id=\"features\" texts={texts} title={title} text={text}>\n      <ul className=\"grid gap-4 sm:grid-cols-2 lg:grid-cols-3\">\n        {items.map((item, i) => (\n          <li key={item.title ?? item.text}>\n            <Card className=\"h-full space-y-2 p-card\">\n              {item.title && (\n                <h3 className=\"text-lg font-semibold\" {...mark(texts, `items.${i}.title`)}>\n                  {item.title}\n                </h3>\n              )}\n              {item.text && (\n                <p className=\"text-muted-foreground\" {...mark(texts, `items.${i}.text`)}>\n                  {item.text}\n                </p>\n              )}\n            </Card>\n          </li>\n        ))}\n      </ul>\n    </Section>\n  );\n}\n\n/** Records shown as cards, e.g. the classes a studio offers. */\nexport function RecordCards({\n  texts,\n  id,\n  title,\n  text,\n  cards,\n}: {\n  id: string;\n  title?: string;\n  text?: string;\n  cards: { key: string | number; title: string; text?: string; badge?: string }[];\n  texts?: string;\n}) {\n  if (cards.length === 0) return null;\n  return (\n    <Section id={id} texts={texts} title={title} text={text}>\n      <ul className=\"grid gap-4 sm:grid-cols-2 lg:grid-cols-3\">\n        {cards.map((card) => (\n          <li key={card.key}>\n            <Card className=\"flex h-full flex-col gap-2 p-card\">\n              <h3 className=\"text-lg font-semibold\">{card.title}</h3>\n              {card.text && <p className=\"flex-1 text-muted-foreground\">{card.text}</p>}\n              {card.badge && (\n                <p className=\"mt-2\">\n                  <span className=\"rounded-md bg-accent px-2 py-0.5 text-xs font-semibold text-accent-foreground\">\n                    {card.badge}\n                  </span>\n                </p>\n              )}\n            </Card>\n          </li>\n        ))}\n      </ul>\n    </Section>\n  );\n}\n\nexport function Pricing({\n  texts,\n  title,\n  text,\n  plans,\n  link,\n}: {\n  title?: string;\n  text?: string;\n  plans: {\n    name?: string;\n    price?: string;\n    period?: string;\n    text?: string;\n    features?: string[];\n    button?: string;\n  }[];\n  link?: LandingLink;\n  texts?: string;\n}) {\n  return (\n    <Section id=\"pricing\" texts={texts} title={title} text={text}>\n      <ul className=\"grid gap-4 md:grid-cols-2 lg:grid-cols-3\">\n        {plans.map((plan, i) => (\n          <li key={plan.name}>\n            <Card className=\"flex h-full flex-col gap-4 p-card\">\n              <h3 className=\"text-lg font-semibold\" {...mark(texts, `items.${i}.name`)}>\n                {plan.name}\n              </h3>\n              {plan.price && (\n                <p>\n                  <span\n                    className=\"text-3xl font-bold tabular-nums\"\n                    {...mark(texts, `items.${i}.price`)}\n                  >\n                    {plan.price}\n                  </span>{\" \"}\n                  {plan.period && (\n                    <span className=\"text-muted-foreground\" {...mark(texts, `items.${i}.period`)}>\n                      {plan.period}\n                    </span>\n                  )}\n                </p>\n              )}\n              {plan.text && (\n                <p className=\"text-muted-foreground\" {...mark(texts, `items.${i}.text`)}>\n                  {plan.text}\n                </p>\n              )}\n              {plan.features && (\n                <ul className=\"flex-1 space-y-2\">\n                  {plan.features.map((feature, j) => (\n                    <li key={feature} className=\"flex gap-2\">\n                      <Check aria-hidden className=\"mt-0.5 size-5 shrink-0 text-primary\" />\n                      <span {...mark(texts, `items.${i}.features.${j}`)}>{feature}</span>\n                    </li>\n                  ))}\n                </ul>\n              )}\n              {link && (\n                <Link to={link.to} className={buttonVariants({ variant: \"outline\" })}>\n                  <span {...mark(texts, `items.${i}.button`)}>{plan.button ?? link.label}</span>\n                </Link>\n              )}\n            </Card>\n          </li>\n        ))}\n      </ul>\n    </Section>\n  );\n}\n\nexport function Testimonials({\n  texts,\n  title,\n  items,\n}: {\n  title?: string;\n  items: { quote?: string; name?: string; role?: string }[];\n  texts?: string;\n}) {\n  return (\n    <Section id=\"testimonials\" texts={texts} title={title}>\n      <ul className=\"grid gap-4 md:grid-cols-2 lg:grid-cols-3\">\n        {items.map((item, i) => (\n          <li key={item.quote}>\n            <Card className=\"h-full p-card\">\n              <figure className=\"space-y-4\">\n                <blockquote className=\"text-lg\">\n                  “<span {...mark(texts, `items.${i}.quote`)}>{item.quote}</span>”\n                </blockquote>\n                <figcaption className=\"text-sm\">\n                  <span className=\"font-semibold\" {...mark(texts, `items.${i}.name`)}>\n                    {item.name}\n                  </span>\n                  {item.role && (\n                    <span className=\"text-muted-foreground\">\n                      , <span {...mark(texts, `items.${i}.role`)}>{item.role}</span>\n                    </span>\n                  )}\n                </figcaption>\n              </figure>\n            </Card>\n          </li>\n        ))}\n      </ul>\n    </Section>\n  );\n}\n\n/** Questions that open in place; the browser handles the keyboard and the expanded state. */\nexport function Faq({\n  texts,\n  title,\n  items,\n}: {\n  title?: string;\n  items: { question?: string; answer?: string }[];\n  texts?: string;\n}) {\n  return (\n    <Section id=\"faq\" texts={texts} title={title}>\n      <div className=\"max-w-3xl divide-y border-y\">\n        {items.map((item, i) => (\n          <details key={item.question} className=\"group\">\n            <summary className=\"flex min-h-14 cursor-pointer list-none items-center justify-between gap-4 py-3 font-semibold outline-none focus-visible:ring-2 focus-visible:ring-ring [&::-webkit-details-marker]:hidden\">\n              <span {...mark(texts, `items.${i}.question`)}>{item.question}</span>\n              <ChevronDown\n                aria-hidden\n                className=\"size-5 shrink-0 transition-transform group-open:rotate-180\"\n              />\n            </summary>\n            <p className=\"pb-4 text-muted-foreground\" {...mark(texts, `items.${i}.answer`)}>\n              {item.answer}\n            </p>\n          </details>\n        ))}\n      </div>\n    </Section>\n  );\n}\n\nexport function CallToAction({\n  texts,\n  title,\n  text,\n  link,\n}: {\n  title: string;\n  text?: string;\n  link?: LandingLink;\n  texts?: string;\n}) {\n  return (\n    <section className=\"mx-auto max-w-6xl px-5 py-16\">\n      <div className=\"rounded-xl bg-primary px-6 py-12 text-primary-foreground sm:px-12\">\n        <h2 className=\"text-2xl font-bold sm:text-3xl\" {...mark(texts, \"title\")}>\n          {title}\n        </h2>\n        {text && (\n          <p className=\"mt-3 max-w-2xl text-lg\" {...mark(texts, \"text\")}>\n            {text}\n          </p>\n        )}\n        {link && (\n          <Link\n            to={link.to}\n            className={cn(buttonVariants({ variant: \"secondary\" }), \"mt-8 h-12 px-6 text-base\")}\n          >\n            <span {...mark(texts, \"button\")}>{link.label}</span>\n          </Link>\n        )}\n      </div>\n    </section>\n  );\n}\n",
  "src/kit/ModelForm.tsx": "// Smithable app kit: a create/edit form for any model, validated with the model's Zod schema.\n// To customise a form, copy this file into src/custom/components/ and edit the copy.\nimport { Calculator, CircleAlert } from \"lucide-react\";\nimport { useRef, useState } from \"react\";\nimport type { z } from \"zod\";\nimport { Button } from \"#/components/ui/button\";\nimport { Card } from \"#/components/ui/card\";\nimport { Label } from \"#/components/ui/input\";\nimport { FieldInput } from \"./FieldInput\";\nimport { formatValue, fromInput, toInput } from \"./format\";\nimport {\n  type AppUi,\n  editorMarker,\n  type FieldUi,\n  type ModelUi,\n  type Options,\n  textMarker,\n} from \"./model\";\n\ninterface ModelFormProps<S extends z.ZodType> {\n  ui: ModelUi;\n  app: AppUi;\n  schema: S;\n  /** The stored record when editing; omit to create a new one. */\n  initial?: Record<string, unknown>;\n  /** Choices for reference fields, e.g. { customerId: [...] }. */\n  options?: Options;\n  submitLabel: string;\n  onSubmit: (values: z.output<S>) => Promise<unknown>;\n  onCancel?: () => void;\n  /** The cancel button's text, e.g. \"Back\" in a step of an onboarding. */\n  cancelLabel?: string;\n  onDelete?: () => Promise<unknown>;\n  /** Shows the record without letting it be changed. */\n  readOnly?: boolean;\n  /** These fields first, in this order; the others follow. */\n  fieldOrder?: string[];\n}\n\nexport function ModelForm<S extends z.ZodType>(props: ModelFormProps<S>) {\n  const {\n    app,\n    schema,\n    initial,\n    options,\n    submitLabel,\n    onSubmit,\n    onCancel,\n    cancelLabel,\n    onDelete,\n    readOnly,\n  } = props;\n  const ui = ordered(props.ui, props.fieldOrder);\n  const [inputs, setInputs] = useState(() => initialInputs(ui, initial));\n  const [errors, setErrors] = useState<Record<string, string>>({});\n  // Computed fields follow what has been entered so far.\n  // The record comes first so values that are not inputs (like related lines) are included.\n  const computed = ui.compute?.({ ...initial, ...storedValues(ui, inputs) }) ?? {};\n  const [failure, setFailure] = useState<string>();\n  const [busy, setBusy] = useState(false);\n  const confirmDelete = useRef<HTMLDialogElement>(null);\n  const recordName = initial?.[ui.titleField];\n\n  async function submit(event: React.FormEvent) {\n    event.preventDefault();\n    const values = storedValues(ui, inputs);\n    const result = schema.safeParse(values);\n    if (!result.success) {\n      const messages: Record<string, string> = {};\n      for (const issue of result.error.issues) {\n        const field = ui.fields.find((f) => f.name === issue.path[0]);\n        if (field && !messages[field.name])\n          messages[field.name] = friendly(field, issue, values[field.name]);\n      }\n      setErrors(messages);\n      return;\n    }\n    setErrors({});\n    await run(() => onSubmit(result.data));\n  }\n\n  async function run(action: () => Promise<unknown>) {\n    setBusy(true);\n    setFailure(undefined);\n    try {\n      await action();\n    } catch (error) {\n      setFailure(failureMessage(ui, error));\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  return (\n    <Card className=\"max-w-3xl\">\n      <form onSubmit={submit} noValidate className=\"space-y-6 p-card\">\n        {!readOnly && ui.fields.some((f) => f.required && !f.computed) && (\n          <p className=\"text-sm text-muted-foreground\">\n            Fields marked <span className=\"text-destructive\">*</span> are required.\n          </p>\n        )}\n        <fieldset disabled={readOnly} className=\"space-y-6\">\n          {ui.fields.map((field) => {\n            const id = `field-${field.name}`;\n            const error = errors[field.name];\n            const inline = field.kind === \"bool\";\n            const described =\n              [field.help && `${id}-help`, error && `${id}-error`].filter(Boolean).join(\" \") ||\n              undefined;\n            return (\n              <div\n                key={field.name}\n                className={inline ? \"flex items-center gap-3\" : \"space-y-2\"}\n                {...editorMarker(ui, field, \"field\")}\n              >\n                {!inline && (\n                  <Label htmlFor={id}>\n                    <span {...textMarker(`models.${ui.model}.fields.${field.name}.label`)}>\n                      {field.label}\n                    </span>\n                    {field.required && <span className=\"text-destructive\"> *</span>}\n                  </Label>\n                )}\n                {field.computed ? (\n                  <p\n                    id={id}\n                    className=\"flex min-h-control items-center gap-2 rounded-md bg-muted px-3 text-sm font-semibold tabular-nums\"\n                  >\n                    <Calculator aria-hidden className=\"size-5 text-muted-foreground\" />\n                    {formatValue(field, computed[field.name], app)}\n                    <span className=\"sr-only\">(calculated)</span>\n                  </p>\n                ) : (\n                  <FieldInput\n                    field={field}\n                    id={id}\n                    value={inputs[field.name] ?? \"\"}\n                    invalid={error !== undefined}\n                    describedBy={described}\n                    options={options}\n                    onChange={(value) =>\n                      setInputs((current) => ({ ...current, [field.name]: value }))\n                    }\n                  />\n                )}\n                {inline && <Label htmlFor={id}>{field.label}</Label>}\n                {field.help && (\n                  <p id={`${id}-help`} className=\"text-sm text-muted-foreground\">\n                    {field.help}\n                  </p>\n                )}\n                {error && (\n                  <p\n                    id={`${id}-error`}\n                    className=\"flex items-center gap-1.5 text-sm text-destructive\"\n                  >\n                    <CircleAlert aria-hidden className=\"size-4 shrink-0\" />\n                    {error}\n                  </p>\n                )}\n              </div>\n            );\n          })}\n        </fieldset>\n        {failure && (\n          <p\n            role=\"alert\"\n            className=\"flex items-start gap-2 rounded-md border border-destructive p-3 text-sm text-destructive\"\n          >\n            <CircleAlert aria-hidden className=\"mt-0.5 size-4 shrink-0\" />\n            {failure}\n          </p>\n        )}\n        <div className=\"flex flex-wrap items-center gap-3 border-t pt-6\">\n          {!readOnly && (\n            <Button type=\"submit\" disabled={busy}>\n              {busy ? \"Saving…\" : submitLabel}\n            </Button>\n          )}\n          {onCancel && (\n            <Button type=\"button\" variant=\"outline\" onClick={onCancel} disabled={busy}>\n              {cancelLabel ?? (readOnly ? \"Back\" : \"Cancel\")}\n            </Button>\n          )}\n          {onDelete && (\n            <Button\n              type=\"button\"\n              variant=\"outline\"\n              className=\"ml-auto border-destructive text-destructive\"\n              disabled={busy}\n              onClick={() => confirmDelete.current?.showModal()}\n            >\n              Delete\n            </Button>\n          )}\n          {onDelete && (\n            // Opening it focuses Cancel, the first button; Escape closes it.\n            <dialog\n              ref={confirmDelete}\n              aria-labelledby=\"delete-title\"\n              className=\"m-auto w-[calc(100%-2.5rem)] max-w-md rounded-lg border bg-card p-card text-card-foreground backdrop:bg-black/50\"\n            >\n              <h2 id=\"delete-title\" className=\"text-lg font-semibold\">\n                Delete{\" \"}\n                {typeof recordName === \"string\" && recordName\n                  ? `“${recordName}”`\n                  : `this ${ui.label.toLowerCase()}`}\n                ?\n              </h2>\n              <p className=\"mt-2 text-muted-foreground\">This cannot be undone.</p>\n              <div className=\"mt-6 flex flex-wrap justify-end gap-3\">\n                <Button\n                  type=\"button\"\n                  variant=\"outline\"\n                  onClick={() => confirmDelete.current?.close()}\n                >\n                  Cancel\n                </Button>\n                <Button\n                  type=\"button\"\n                  variant=\"destructive\"\n                  onClick={() => {\n                    confirmDelete.current?.close();\n                    run(onDelete);\n                  }}\n                >\n                  Delete {ui.label.toLowerCase()}\n                </Button>\n              </div>\n            </dialog>\n          )}\n        </div>\n      </form>\n    </Card>\n  );\n}\n\n/** A message a non-developer understands, instead of Zod's technical text. */\nfunction friendly(field: FieldUi, issue: z.core.$ZodIssue, value: unknown): string {\n  if (value === null || value === undefined) return \"Required\";\n  if (issue.code !== \"invalid_type\") return issue.message;\n  switch (field.kind) {\n    case \"int\":\n      return \"Enter a whole number\";\n    case \"decimal\":\n    case \"money\":\n      return \"Enter a number\";\n    case \"date\":\n      return \"Enter a valid date\";\n    case \"datetime\":\n      return \"Enter a valid date and time\";\n    default:\n      return issue.message;\n  }\n}\n\n/** Explains server errors; a unique column shows which field is taken. */\nfunction failureMessage(ui: ModelUi, error: unknown): string {\n  const message = error instanceof Error ? error.message : \"\";\n  // With several columns (unique per owner), the last one is the field.\n  const column = /UNIQUE constraint failed: (?:\\w+\\.\\w+, )*\\w+\\.(\\w+)/.exec(message)?.[1];\n  const field = ui.fields.find(\n    (f) => f.name.replace(/[A-Z]/g, (c) => `_${c.toLowerCase()}`) === column,\n  );\n  if (field)\n    return `Another ${ui.label.toLowerCase()} already has this ${field.label.toLowerCase()}.`;\n  if (message.includes(\"FOREIGN KEY constraint failed\")) {\n    return `This ${ui.label.toLowerCase()} is still used by other records. Change or delete those first.`;\n  }\n  return message || \"Something went wrong. Please try again.\";\n}\n\n/** Form inputs for a record being edited, or for a new one: defaults, including formula defaults. */\nfunction initialInputs(\n  ui: ModelUi,\n  initial?: Record<string, unknown>,\n): Record<string, string | boolean> {\n  const inputs: Record<string, string | boolean> = {};\n  const values: Record<string, unknown> = {};\n  for (const field of ui.fields) {\n    if (field.computed) continue;\n    const suggested = ui.defaults?.[field.name];\n    const value = initial ? initial[field.name] : suggested ? suggested(values) : field.default;\n    values[field.name] = value;\n    inputs[field.name] = toInput(field, value);\n  }\n  return inputs;\n}\n\n/** The values to validate and save: every entered field, never computed ones. */\nfunction storedValues(\n  ui: ModelUi,\n  inputs: Record<string, string | boolean>,\n): Record<string, unknown> {\n  return Object.fromEntries(\n    ui.fields.filter((f) => !f.computed).map((f) => [f.name, fromInput(f, inputs[f.name] ?? \"\")]),\n  );\n}\n\n/** The model's fields with `order` first, in that order. */\nfunction ordered(ui: ModelUi, order?: string[]): ModelUi {\n  if (!order) return ui;\n  const rank = (name: string) => {\n    const i = order.indexOf(name);\n    return i === -1 ? order.length : i;\n  };\n  return { ...ui, fields: [...ui.fields].sort((a, b) => rank(a.name) - rank(b.name)) };\n}\n",
  "src/kit/ModelTable.tsx": "// Smithable app kit: a table of records for any model. Choice values show as badges.\n// To customise a table, copy this file into src/custom/components/ and edit the copy.\nimport { ChevronRight } from \"lucide-react\";\nimport { Badge } from \"#/components/ui/badge\";\nimport { Card } from \"#/components/ui/card\";\nimport {\n  Table,\n  TableBody,\n  TableCell,\n  TableHead,\n  TableHeader,\n  TableRow,\n} from \"#/components/ui/table\";\nimport { cn } from \"#/lib/utils\";\nimport { displayValue, formatValue } from \"./format\";\nimport { type AppUi, editorMarker, type FieldUi, type ModelUi, type Row } from \"./model\";\n\ninterface ModelTableProps<R extends Row> {\n  ui: ModelUi;\n  app: AppUi;\n  rows: R[];\n  /** Opens a row; without it rows are not clickable. */\n  onOpen?: (row: R) => void;\n  /** Columns to leave out, e.g. the reference back to the record a list belongs to. */\n  hide?: string[];\n  /** Shown when there are no records, e.g. a \"New …\" button. */\n  emptyAction?: React.ReactNode;\n  /** Replaces \"No … yet\", e.g. when a search matches nothing. */\n  emptyMessage?: string;\n  /** The columns to show, in order, instead of the model's default ones. */\n  columns?: string[];\n  /** A second field shown under a column's value, e.g. { email: \"phone\" }. */\n  below?: Record<string, string>;\n  /** The page showing the table, so the preview editor can change its columns. */\n  page?: string;\n}\n\nexport function ModelTable<R extends Row>({\n  ui,\n  app,\n  rows,\n  onOpen,\n  hide = [],\n  emptyAction,\n  emptyMessage,\n  columns: chosen,\n  below = {},\n  page,\n}: ModelTableProps<R>) {\n  const shown = ui.compute ? rows.map((row) => ({ ...row, ...ui.compute?.(row) }) as R) : rows;\n  const columns = (chosen ?? ui.columns)\n    .filter((name) => !hide.includes(name))\n    .flatMap((name) => ui.fields.filter((f) => f.name === name));\n  if (rows.length === 0) {\n    return (\n      <Card className=\"flex flex-col items-center gap-3 px-6 py-16 text-center\">\n        {emptyMessage ? (\n          <p className=\"font-medium\">{emptyMessage}</p>\n        ) : (\n          <>\n            <p className=\"font-medium\">No {ui.pluralLabel.toLowerCase()} yet</p>\n            <p className=\"text-sm text-muted-foreground\">Create the first one to get started.</p>\n            {emptyAction}\n          </>\n        )}\n      </Card>\n    );\n  }\n  const second = (field: FieldUi) => ui.fields.find((f) => f.name === below[field.name]);\n  // A column with a second field below its value: both on their own line.\n  const stacked = (field: FieldUi, row: R) => {\n    const other = second(field);\n    return other ? (\n      <>\n        <span className=\"block\">{cell(field, row)}</span>\n        <span className=\"block text-muted-foreground\">{cell(other, row)}</span>\n      </>\n    ) : (\n      cell(field, row)\n    );\n  };\n  const title = columns.find((f) => f.name === ui.titleField) ?? columns[0];\n  const others = columns.filter((f) => f !== title);\n  const status = others.find((f) => f.kind === \"choice\");\n  const amount = others.find((f) => numeric(f.kind));\n  const date = others.find((f) => f.kind === \"date\" || f.kind === \"datetime\");\n  const secondary = others.find((f) => f !== status && f !== amount && f !== date);\n  const cell = (field: FieldUi, row: R) => {\n    const text = formatValue(field, displayValue(field, row), app);\n    if (field.kind !== \"choice\" || text === \"—\") return text;\n    const tone = field.choices?.find((c) => c.value === displayValue(field, row))?.tone;\n    return <Badge variant={tone}>{text}</Badge>;\n  };\n  // Opening a record is a real button (keyboard and screen readers), stretched over the row.\n  const open = (row: R, children: React.ReactNode, className?: string) =>\n    onOpen ? (\n      <button\n        type=\"button\"\n        onClick={() => onOpen(row)}\n        className={cn(\n          \"cursor-pointer text-left font-semibold outline-none after:absolute after:inset-0 focus-visible:after:rounded-md focus-visible:after:ring-2 focus-visible:after:ring-ring\",\n          className,\n        )}\n      >\n        {children}\n      </button>\n    ) : (\n      children\n    );\n  return (\n    <>\n      {/* Phones: one card per record: its name and status, a contact or other identifier, then a date and a key amount. */}\n      <ul className=\"space-y-3 md:hidden\">\n        {shown.map((row) => (\n          <li key={row.id}>\n            <Card className=\"relative space-y-3 p-5 hover:bg-accent/40\">\n              <div className=\"flex items-start justify-between gap-3\">\n                <div className=\"min-w-0 space-y-1\">\n                  {title && open(row, cell(title, row), \"break-words text-base font-semibold\")}\n                  {secondary && <p className=\"break-words text-sm\">{stacked(secondary, row)}</p>}\n                </div>\n                {status ? (\n                  <div className=\"shrink-0\">{cell(status, row)}</div>\n                ) : (\n                  onOpen && <ChevronRight aria-hidden className=\"mt-0.5 size-5 shrink-0\" />\n                )}\n              </div>\n              {(date || amount) && (\n                <p className=\"flex items-baseline justify-between gap-3 pt-2 text-sm\">\n                  <span className=\"text-muted-foreground\">\n                    {date ? cell(date, row) : amount?.label}\n                  </span>\n                  {amount && (\n                    <span className=\"text-lg font-semibold whitespace-nowrap tabular-nums\">\n                      {cell(amount, row)}\n                    </span>\n                  )}\n                </p>\n              )}\n            </Card>\n          </li>\n        ))}\n      </ul>\n      <Card className=\"hidden overflow-hidden md:block\">\n        <Table>\n          <TableHeader>\n            <TableRow className=\"hover:bg-transparent\">\n              {columns.map((field) => (\n                <TableHead\n                  key={field.name}\n                  className={numeric(field.kind) ? \"text-right\" : undefined}\n                  {...editorMarker(ui, field, \"column\", page)}\n                >\n                  {second(field) ? `${field.label} / ${second(field)?.label}` : field.label}\n                </TableHead>\n              ))}\n            </TableRow>\n          </TableHeader>\n          <TableBody>\n            {shown.map((row) => (\n              <TableRow key={row.id} className={onOpen ? \"relative cursor-pointer\" : undefined}>\n                {columns.map((field) => (\n                  <TableCell\n                    key={field.name}\n                    className={cn(\n                      numeric(field.kind) && \"text-right tabular-nums\",\n                      field.name === ui.titleField && \"font-semibold\",\n                    )}\n                  >\n                    {field === title ? open(row, cell(field, row)) : stacked(field, row)}\n                  </TableCell>\n                ))}\n              </TableRow>\n            ))}\n          </TableBody>\n        </Table>\n      </Card>\n    </>\n  );\n}\n\nfunction numeric(kind: string): boolean {\n  return kind === \"int\" || kind === \"decimal\" || kind === \"money\";\n}\n",
  "src/kit/Onboarding.tsx": "// Smithable app kit: the frame of a first-time setup in steps, with its progress.\n// To change it, copy this file into src/custom/components/ and edit the copy.\nimport { cn } from \"#/lib/utils\";\n\nexport function OnboardingLayout({\n  title,\n  subtitle,\n  step,\n  count,\n  stepTitle,\n  stepText,\n  footer,\n  children,\n}: {\n  title: string;\n  subtitle?: string;\n  /** The current step, from 0. */\n  step: number;\n  count: number;\n  stepTitle: string;\n  stepText?: string;\n  /** E.g. a \"Do this later\" link. */\n  footer?: React.ReactNode;\n  children: React.ReactNode;\n}) {\n  return (\n    <main className=\"mx-auto max-w-3xl px-5 py-12 sm:py-20\">\n      <h1 className=\"text-3xl font-bold sm:text-4xl\">{title}</h1>\n      {subtitle && <p className=\"mt-2 text-muted-foreground\">{subtitle}</p>}\n      <p className=\"mt-8 text-xs font-semibold uppercase tracking-wide text-muted-foreground\">\n        Step {step + 1} of {count}\n      </p>\n      <div aria-hidden className=\"mt-2 flex gap-2\">\n        {Array.from({ length: count }, (_, i) => i).map((n) => (\n          <span\n            key={n}\n            className={cn(\"h-1 flex-1 rounded-full\", n <= step ? \"bg-primary\" : \"bg-border\")}\n          />\n        ))}\n      </div>\n      <h2 className=\"mt-8 text-xl font-semibold\">{stepTitle}</h2>\n      {stepText && <p className=\"mt-1 text-muted-foreground\">{stepText}</p>}\n      <div className=\"mt-4\">{children}</div>\n      {footer && <div className=\"mt-6\">{footer}</div>}\n    </main>\n  );\n}\n",
  "src/kit/SearchBox.tsx": "// Smithable app kit: a search box that reports its text shortly after typing stops.\nimport { Search } from \"lucide-react\";\nimport { useEffect, useState } from \"react\";\nimport { Input } from \"#/components/ui/input\";\n\nexport function SearchBox({\n  value,\n  placeholder,\n  onSearch,\n}: {\n  value: string;\n  placeholder: string;\n  onSearch: (text: string) => void;\n}) {\n  const [text, setText] = useState(value);\n  useEffect(() => {\n    if (text === value) return;\n    const timer = setTimeout(() => onSearch(text.trim()), 250);\n    return () => clearTimeout(timer);\n  }, [text, value, onSearch]);\n  return (\n    <div className=\"relative mb-6 max-w-md\">\n      <Input\n        type=\"search\"\n        aria-label={placeholder}\n        placeholder={placeholder}\n        value={text}\n        onChange={(e) => setText(e.target.value)}\n        className=\"pr-10\"\n      />\n      <Search\n        aria-hidden\n        className=\"pointer-events-none absolute top-1/2 right-3 size-5 -translate-y-1/2 text-muted-foreground\"\n      />\n    </div>\n  );\n}\n",
  "src/kit/SignIn.tsx": "// Smithable app kit: the sign-in card, with a button per sign-in provider.\n// In development it also offers signing in as any role, without contacting a provider.\nimport { useState } from \"react\";\nimport { Button } from \"#/components/ui/button\";\nimport { Card } from \"#/components/ui/card\";\n\nconst PROVIDER_LABELS: Record<string, string> = { google: \"Google\", facebook: \"Facebook\" };\n\nexport function SignIn({\n  appName,\n  providers,\n  missing,\n  devRoles,\n  onProvider,\n  onDevRole,\n}: {\n  appName: string;\n  /** Providers that are set up, in button order. */\n  providers: string[];\n  /** Providers in the spec whose keys are not configured yet. */\n  missing: string[];\n  /** Roles to sign in as; only given in development. */\n  devRoles?: string[];\n  onProvider: (provider: string) => Promise<unknown>;\n  onDevRole?: (role: string) => Promise<unknown>;\n}) {\n  const [failure, setFailure] = useState<string>();\n  const [busy, setBusy] = useState(false);\n  async function run(action: () => Promise<unknown>) {\n    setBusy(true);\n    setFailure(undefined);\n    try {\n      await action();\n    } catch (error) {\n      setFailure(error instanceof Error ? error.message : \"Could not sign in. Please try again.\");\n      setBusy(false);\n    }\n  }\n  return (\n    <Card className=\"mx-auto mt-10 max-w-sm space-y-5 p-card\">\n      <h1 className=\"text-2xl font-bold\">Sign in to {appName}</h1>\n      {providers.map((provider) => (\n        <Button\n          key={provider}\n          className=\"w-full\"\n          disabled={busy}\n          onClick={() => run(() => onProvider(provider))}\n        >\n          Continue with {PROVIDER_LABELS[provider] ?? provider}\n        </Button>\n      ))}\n      {/* Setup notes are for the developer; visitors only learn that sign-in is unavailable. */}\n      {devRoles && missing.length > 0 && (\n        <p className=\"text-xs text-muted-foreground\">\n          Sign-in with {missing.map((p) => PROVIDER_LABELS[p] ?? p).join(\" and \")} is not set up\n          yet: its keys are missing from the environment. See the README.\n        </p>\n      )}\n      {!devRoles && providers.length === 0 && (\n        <p className=\"text-muted-foreground\">\n          Signing in is not available right now. Please contact whoever runs {appName}.\n        </p>\n      )}\n      {failure && (\n        <p className=\"rounded-md bg-destructive/10 p-3 text-sm text-destructive\">{failure}</p>\n      )}\n      {devRoles && onDevRole && (\n        <div className=\"space-y-2 border-t pt-4\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-muted-foreground\">\n            Development only\n          </p>\n          {devRoles.map((role) => (\n            <Button\n              key={role}\n              variant=\"outline\"\n              className=\"w-full\"\n              disabled={busy}\n              onClick={() => run(() => onDevRole(role))}\n            >\n              Sign in as {role}\n            </Button>\n          ))}\n        </div>\n      )}\n    </Card>\n  );\n}\n",
  "src/kit/access.ts": "// Smithable app kit: who may read, create, change and delete records, and open pages.\n// Every generated data function checks access here, so the rules live in one place.\nimport { redirect } from \"@tanstack/react-router\";\n\n/** The signed-in user, or null for a visitor who has not signed in. */\nexport interface Viewer {\n  id: string;\n  name: string;\n  email: string;\n  role: string;\n}\n\n/** Who may do something: anyone (public), users with one of `roles`, and a record's owner. */\nexport interface Rule {\n  public: boolean;\n  roles: readonly string[];\n  owner: boolean;\n}\n\nexport interface ModelAccess {\n  read: Rule;\n  create: Rule;\n  write: Rule;\n  delete: Rule;\n}\n\nexport class AccessDenied extends Error {\n  constructor(signedIn: boolean) {\n    super(signedIn ? \"You are not allowed to do this.\" : \"Please sign in first.\");\n  }\n}\n\n/** Whether the viewer may do something; `ownerId` is the owner of the record involved, if any. */\nexport function allows(rule: Rule, viewer: Viewer | null, ownerId?: string | null): boolean {\n  if (rule.public) return true;\n  if (!viewer) return false;\n  if (rule.roles.includes(viewer.role)) return true;\n  return rule.owner && ownerId != null && ownerId === viewer.id;\n}\n\nexport function check(rule: Rule, viewer: Viewer | null, ownerId?: string | null): void {\n  if (!allows(rule, viewer, ownerId)) throw new AccessDenied(viewer !== null);\n}\n\n/** Which records the viewer may read: all of them, only their own, or none. */\nexport function readScope(rule: Rule, viewer: Viewer | null): \"all\" | \"own\" | \"none\" {\n  if (allows(rule, viewer)) return \"all\";\n  return viewer && rule.owner ? \"own\" : \"none\";\n}\n\n/** For a page's beforeLoad: sends visitors to sign in, and refuses users without the role. */\nexport function guardPage(rule: Rule, viewer: Viewer | null, href: string): void {\n  if (allows(rule, viewer)) return;\n  if (!viewer) throw redirect({ href: `/sign-in?redirect=${encodeURIComponent(href)}` });\n  throw new AccessDenied(true);\n}\n",
  "src/kit/aggregate.ts": "// Smithable app kit: the numbers a dashboard shows, worked out from records the viewer may read.\n\n/** The sum of a number over records; empty values count as nothing. */\nexport function sum<R>(rows: R[], value: (row: R) => unknown): number {\n  return rows.reduce((total, row) => total + (Number(value(row)) || 0), 0);\n}\n\n/** The average of a number over records that have one, or null when none do. */\nexport function average<R>(rows: R[], value: (row: R) => unknown): number | null {\n  const numbers = rows.map(value).filter((v) => v !== null && v !== undefined) as number[];\n  return numbers.length ? sum(numbers, Number) / numbers.length : null;\n}\n\n/**\n * One total per month, for the last `months` months up to the latest record's month, with\n * empty months as 0. Months are \"2026-09\", from a date or a date and time (in UTC).\n */\nexport function byMonth<R>(\n  rows: R[],\n  date: (row: R) => unknown,\n  value: (row: R) => number,\n  months = 6,\n): { month: string; value: number }[] {\n  const totals = new Map<string, number>();\n  for (const row of rows) {\n    const d = date(row);\n    if (d === null || d === undefined) continue;\n    const month = (d instanceof Date ? d.toISOString() : String(d)).slice(0, 7);\n    totals.set(month, (totals.get(month) ?? 0) + value(row));\n  }\n  const last = [...totals.keys()].sort().at(-1);\n  if (!last) return [];\n  const [year, month] = last.split(\"-\").map(Number) as [number, number];\n  return Array.from({ length: months }, (_, i) => {\n    const d = new Date(Date.UTC(year, month - months + i, 1));\n    const key = d.toISOString().slice(0, 7);\n    return { month: key, value: totals.get(key) ?? 0 };\n  });\n}\n\n/** The newest records first: the highest ids. */\nexport function latest<R extends { id: number }>(rows: R[], limit: number): R[] {\n  return [...rows].sort((a, b) => b.id - a.id).slice(0, limit);\n}\n",
  "src/kit/format.ts": "// Smithable app kit: converts stored values to display text and to form input text, and back.\nimport type { AppUi, FieldUi } from \"./model\";\n\n/** The value to show for a field of a row: for a reference, the related record's title. */\nexport function displayValue(field: FieldUi, row: Record<string, unknown>): unknown {\n  if (!field.relation) return row[field.name];\n  const related = row[field.relation.key] as Record<string, unknown> | null | undefined;\n  if (!related) return null;\n  return field.relation.titleField === \"id\"\n    ? `#${String(related.id)}`\n    : related[field.relation.titleField];\n}\n\n/** Text for showing a stored value in tables and headings. */\nexport function formatValue(field: FieldUi, value: unknown, app: AppUi): string {\n  if (value === null || value === undefined || value === \"\") return \"—\";\n  switch (field.kind) {\n    case \"money\":\n      return new Intl.NumberFormat(undefined, { style: \"currency\", currency: app.currency }).format(\n        Number(value) / 100,\n      );\n    case \"int\":\n    case \"decimal\":\n      return new Intl.NumberFormat().format(Number(value));\n    case \"bool\":\n      return value ? \"Yes\" : \"No\";\n    case \"date\":\n      return new Intl.DateTimeFormat(undefined, { dateStyle: \"medium\", timeZone: \"UTC\" }).format(\n        new Date(`${String(value)}T00:00:00Z`),\n      );\n    case \"datetime\":\n      return new Intl.DateTimeFormat(undefined, {\n        dateStyle: \"medium\",\n        timeStyle: \"short\",\n        timeZone: app.timeZone,\n      }).format(value instanceof Date ? value : new Date(String(value)));\n    case \"choice\":\n      return field.choices?.find((c) => c.value === value)?.label ?? String(value);\n    case \"relation\":\n    case \"user\":\n      return String(value);\n    default:\n      return String(value);\n  }\n}\n\n/** The form input's text for a stored value. Booleans stay booleans. */\nexport function toInput(field: FieldUi, value: unknown): string | boolean {\n  if (field.kind === \"bool\") return Boolean(value);\n  if (value === null || value === undefined) return \"\";\n  if (field.kind === \"money\") return (Number(value) / 100).toFixed(2);\n  if (field.kind === \"datetime\") {\n    const date = value instanceof Date ? value : new Date(String(value));\n    const local = new Date(date.getTime() - date.getTimezoneOffset() * 60_000);\n    return local.toISOString().slice(0, 16);\n  }\n  return String(value);\n}\n\n/** The stored value for a form input's text. Empty text becomes null. */\nexport function fromInput(field: FieldUi, input: string | boolean): unknown {\n  if (typeof input === \"boolean\") return input;\n  const text = input.trim();\n  if (text === \"\") return null;\n  switch (field.kind) {\n    case \"int\":\n    case \"decimal\":\n      return Number(text.replace(\",\", \".\"));\n    case \"money\":\n      return Math.round(Number(text.replace(\",\", \".\")) * 100);\n    case \"datetime\":\n      return new Date(text);\n    case \"relation\":\n      return Number(text);\n    default:\n      return text;\n  }\n}\n",
  "src/kit/formula.ts": "// Smithable app kit: the spreadsheet functions used by the formulas in src/generated/*.formulas.ts.\n// Blank values behave like blank spreadsheet cells: 0 in arithmetic, \"\" in text.\n\ntype Value = unknown;\n\n/** A number, or 0 for a blank value. */\nfunction n(value: Value): number {\n  return typeof value === \"number\" ? value : value == null || value === \"\" ? 0 : Number(value);\n}\n\n/** Text, or \"\" for a blank value. */\nfunction t(value: Value): string {\n  if (value == null) return \"\";\n  if (value instanceof Date) return value.toISOString();\n  return String(value);\n}\n\n/** A date as YYYY-MM-DD, or \"\" for a blank value. */\nfunction d(value: Value): string {\n  if (value instanceof Date) return value.toISOString().slice(0, 10);\n  return value == null ? \"\" : String(value).slice(0, 10);\n}\n\n/** Comparable form of a value: numbers, dates and text compare like in a spreadsheet. */\nfunction key(value: Value): number | string {\n  if (value instanceof Date) return value.getTime();\n  if (typeof value === \"number\" || typeof value === \"boolean\") return Number(value);\n  return t(value);\n}\n\nfunction compare(op: \"=\" | \"<>\" | \"<\" | \">\" | \"<=\" | \">=\", a: Value, b: Value): boolean {\n  const x = key(a);\n  const y = key(b);\n  switch (op) {\n    case \"=\":\n      return x === y;\n    case \"<>\":\n      return x !== y;\n    case \"<\":\n      return x < y;\n    case \">\":\n      return x > y;\n    case \"<=\":\n      return x <= y;\n    case \">=\":\n      return x >= y;\n  }\n}\n\n/**\n * Rounds half away from zero, like spreadsheets. Float noise far below the last digit is\n * removed first, so 0.5 * 19.99 (9.995) rounds to 10.00 and ROUND(1.005, 2) to 1.01.\n */\nfunction ROUND(value: number, digits = 0): number {\n  const scaled = Number((Math.abs(value) * 10 ** digits).toFixed(9));\n  return (Math.sign(value) * Math.round(scaled)) / 10 ** digits;\n}\n\nfunction TODAY(): string {\n  return new Date().toISOString().slice(0, 10);\n}\n\n/** The current date and time, e.g. for \"placed at\" when a record is created. */\nfunction NOW(): string {\n  return new Date().toISOString();\n}\n\nfunction DATEADD(date: string, amount: number, unit: \"day\" | \"month\" | \"year\"): string {\n  if (date === \"\") return \"\";\n  const value = new Date(`${date}T00:00:00Z`);\n  if (unit === \"day\") value.setUTCDate(value.getUTCDate() + amount);\n  else {\n    const day = value.getUTCDate();\n    value.setUTCDate(1);\n    if (unit === \"month\") value.setUTCMonth(value.getUTCMonth() + amount);\n    else value.setUTCFullYear(value.getUTCFullYear() + amount);\n    const last = new Date(\n      Date.UTC(value.getUTCFullYear(), value.getUTCMonth() + 1, 0),\n    ).getUTCDate();\n    value.setUTCDate(Math.min(day, last)); // 31 January + 1 month is 28 or 29 February\n  }\n  return value.toISOString().slice(0, 10);\n}\n\n/** Days from `start` to `end`. */\nfunction DAYS(end: string, start: string): number {\n  if (end === \"\" || start === \"\") return 0;\n  return Math.round(\n    (Date.parse(`${end}T00:00:00Z`) - Date.parse(`${start}T00:00:00Z`)) / 86_400_000,\n  );\n}\n\n/** The related records a formula aggregates over (a list relation), or none. */\nfunction list(value: Value): Record<string, unknown>[] {\n  return Array.isArray(value) ? value : [];\n}\n\nconst SUM = (values: number[]) => values.reduce((a, b) => a + b, 0);\nconst AVG = (values: number[]) => (values.length ? SUM(values) / values.length : 0);\nconst MIN = (values: number[]) => (values.length ? Math.min(...values) : 0);\nconst MAX = (values: number[]) => (values.length ? Math.max(...values) : 0);\n\n/** Money is stored in cents; formulas work in whole currency units. */\nconst fromCents = (value: Value) => n(value) / 100;\nconst toCents = (value: number) => Math.round(ROUND(value, 2) * 100);\n\nexport const F = {\n  n,\n  t,\n  d,\n  compare,\n  ROUND,\n  TODAY,\n  NOW,\n  DATEADD,\n  DAYS,\n  list,\n  SUM,\n  AVG,\n  MIN,\n  MAX,\n  fromCents,\n  toCents,\n};\n",
  "src/kit/model.ts": "// Smithable app kit: describes models to the generic table and form components.\n// Each model's description is in src/generated/<model>.ts.\n\nexport type FieldKind =\n  | \"string\"\n  | \"text\"\n  | \"int\"\n  | \"decimal\"\n  | \"money\"\n  | \"bool\"\n  | \"date\"\n  | \"datetime\"\n  | \"email\"\n  | \"phone\"\n  | \"url\"\n  | \"choice\"\n  | \"relation\"\n  /** A reference to a user who signs in. */\n  | \"user\";\n\nexport interface FieldUi {\n  name: string;\n  label: string;\n  kind: FieldKind;\n  required: boolean;\n  /** Computed by a formula: shown, never entered. */\n  computed?: boolean;\n  help?: string;\n  /** A choice's tone colours its badge by meaning; without one it is neutral. */\n  choices?: { value: string; label: string; tone?: \"success\" | \"warning\" | \"danger\" }[];\n  /** For a reference: the related record's key in a row, and the field that names it. */\n  relation?: { key: string; titleField: string };\n  default?: string | number | boolean;\n}\n\nexport interface ModelUi {\n  /** The model's name in the spec, e.g. \"Customer\"; none for an action's form. */\n  model?: string;\n  label: string;\n  pluralLabel: string;\n  /** The field that names a record, e.g. \"name\". */\n  titleField: string;\n  /** Fields shown as table columns, in order. */\n  columns: string[];\n  fields: FieldUi[];\n  /** Adds the computed fields to a record. */\n  compute?: (row: Record<string, unknown>) => Record<string, unknown>;\n  /** Values suggested for a new record, computed from the values entered so far. */\n  defaults?: Record<string, (row: Record<string, unknown>) => unknown>;\n}\n\nexport interface AppUi {\n  name: string;\n  currency: string;\n  timeZone?: string;\n}\n\nexport type Row = { id: number } & Record<string, unknown>;\n\n/** Choices for a reference field, keyed by the field's name, e.g. { customerId: [...] }. */\nexport type Options = Record<string, { value: number | string; label: string }[]>;\n\n/**\n * Marks a visible text with where its wording is kept, e.g. \"pages.customers.title\", so the\n * preview editor can change it in place. Only in development.\n */\nexport function textMarker(path: string) {\n  return import.meta.env.DEV ? { \"data-sm-text\": path } : {};\n}\n\n/**\n * Marks an element with the part of the app description it shows, for the preview editor\n * (select a field, drag a column). Only in development: production builds leave it out.\n */\nexport function editorMarker(\n  ui: ModelUi,\n  field?: FieldUi,\n  part?: \"field\" | \"column\",\n  page?: string,\n) {\n  if (!import.meta.env.DEV || !ui.model) return {};\n  const name = field ? (field.relation?.key ?? field.name) : undefined;\n  return {\n    \"data-sm-concept\": name ? `field:${ui.model}.${name}` : `model:${ui.model}`,\n    ...(part ? { \"data-sm-part\": part } : {}),\n    ...(page ? { \"data-sm-page\": page } : {}),\n  };\n}\n",
  "src/kit/search.ts": "// Smithable app kit: the condition for records matching a search box's text.\nimport { type Column, getTableName, or, type SQL, sql, type Table } from \"drizzle-orm\";\n\n/** Records where any of the columns contains the text, ignoring case (SQLite's LIKE). */\nexport function contains(columns: Column[], text: string): SQL | undefined {\n  // % and _ are wildcards in LIKE; the text is matched literally.\n  const pattern = `%${text.replace(/[\\\\%_]/g, (c) => `\\\\${c}`)}%`;\n  return or(...columns.map((column) => sql`${column} like ${pattern} escape '\\\\'`));\n}\n\n/**\n * Records whose reference points at a related record containing the text, e.g. orders whose\n * customer's name matches. The subquery names its table and columns itself: a list's query\n * would otherwise read them as columns of its own table.\n */\nexport function relatedContains(\n  reference: Column,\n  table: Table,\n  columns: Column[],\n  text: string,\n): SQL {\n  const pattern = `%${text.replace(/[\\\\%_]/g, (c) => `\\\\${c}`)}%`;\n  const name = sql.identifier(getTableName(table));\n  const matches = or(\n    ...columns.map((c) => sql`${name}.${sql.identifier(c.name)} like ${pattern} escape '\\\\'`),\n  );\n  return sql`${reference} in (select ${name}.\"id\" from ${name} where ${matches})`;\n}\n",
  "src/kit/security.ts": "// Smithable app kit: the Content Security Policy of the production app's pages. The other\n// security headers come from server.mjs, on every response. In development there are none,\n// so the app can be previewed inside another page (an iframe) and the dev server works.\n\n/**\n * A page's Content Security Policy: only the app's own scripts and those carrying this page's\n * nonce run. Inline style attributes are allowed (a chart's bars are sized with them); inline\n * style elements need the nonce.\n */\nexport function pageHeaders(nonce: string | undefined): Record<string, string> {\n  if (!import.meta.env.PROD || !nonce) return {};\n  return {\n    \"Content-Security-Policy\": [\n      \"default-src 'self'\",\n      `script-src 'self' 'nonce-${nonce}'`,\n      `style-src 'self' 'nonce-${nonce}'`,\n      \"style-src-attr 'unsafe-inline'\",\n      \"img-src 'self' data:\",\n      \"font-src 'self'\",\n      \"connect-src 'self'\",\n      \"object-src 'none'\",\n      \"base-uri 'self'\",\n      \"form-action 'self'\",\n      \"frame-ancestors 'none'\",\n    ].join(\"; \"),\n  };\n}\n",
  "src/lib/auth-client.ts": "// Smithable app kit: Better Auth in the browser, for signing in and out.\nimport { createAuthClient } from \"better-auth/react\";\n\nexport const authClient = createAuthClient();\n",
  "src/lib/utils.ts": "import { type ClassValue, clsx } from \"clsx\";\nimport { twMerge } from \"tailwind-merge\";\n\nexport function cn(...inputs: ClassValue[]) {\n  return twMerge(clsx(inputs));\n}\n",
  "src/router.tsx": "import { createRouter } from \"@tanstack/react-router\";\nimport { createIsomorphicFn } from \"@tanstack/react-start\";\nimport { routeTree } from \"./routeTree.gen\";\n\n/**\n * A new nonce for every server-rendered page: the Content Security Policy allows its scripts.\n * Base64, as CSP nonces usually are (a hex nonce's digit runs can look like card numbers).\n */\nconst ssrOptions = createIsomorphicFn().server(() => ({\n  nonce: btoa(String.fromCharCode(...crypto.getRandomValues(new Uint8Array(16)))),\n}));\n\nexport function getRouter() {\n  return createRouter({\n    routeTree,\n    scrollRestoration: true,\n    defaultPreload: \"intent\",\n    defaultPreloadStaleTime: 0,\n    ssr: ssrOptions(),\n  });\n}\n\ndeclare module \"@tanstack/react-router\" {\n  interface Register {\n    router: ReturnType<typeof getRouter>;\n  }\n}\n",
  "src/routes/api/auth/$.ts": "// Smithable app kit: Better Auth's endpoints (sign-in callbacks, sessions, sign-out).\nimport { createFileRoute } from \"@tanstack/react-router\";\nimport { auth } from \"#/lib/auth\";\n\nexport const Route = createFileRoute(\"/api/auth/$\")({\n  server: {\n    handlers: {\n      GET: ({ request }) => auth.handler(request),\n      POST: ({ request }) => auth.handler(request),\n    },\n  },\n});\n",
  "src/routes/health.ts": "// Smithable app kit: the health endpoint of the deployment contract.\nimport { createFileRoute } from \"@tanstack/react-router\";\nimport { sql } from \"drizzle-orm\";\nimport { db } from \"#/db\";\n\nexport const Route = createFileRoute(\"/health\")({\n  server: {\n    handlers: {\n      GET: () => {\n        db.run(sql`select 1`);\n        return Response.json({ status: \"ok\" });\n      },\n    },\n  },\n});\n",
  "src/styles.css": "/* Smithable app kit: styles built on the theme's tokens in src/theme.css.\n   Colours follow shadcn/ui's token names. */\n@import \"tailwindcss\";\n@import \"./theme.css\";\n\n@custom-variant dark (@media (prefers-color-scheme: dark));\n\n@theme inline {\n  --font-sans: var(--font-body);\n  --color-background: var(--background);\n  --color-foreground: var(--foreground);\n  --color-card: var(--card);\n  --color-card-foreground: var(--card-foreground);\n  --color-primary: var(--primary);\n  --color-primary-foreground: var(--primary-foreground);\n  --color-secondary: var(--secondary);\n  --color-secondary-foreground: var(--secondary-foreground);\n  --color-muted: var(--muted);\n  --color-muted-foreground: var(--muted-foreground);\n  --color-accent: var(--accent);\n  --color-accent-foreground: var(--accent-foreground);\n  --color-destructive: var(--destructive);\n  --color-destructive-foreground: var(--destructive-foreground);\n  --color-border: var(--border);\n  --color-input: var(--input);\n  --color-ring: var(--ring);\n  --color-sidebar: var(--sidebar);\n  --color-sidebar-foreground: var(--sidebar-foreground);\n  --color-success: var(--success);\n  --color-success-foreground: var(--success-foreground);\n  --color-warning: var(--warning);\n  --color-warning-foreground: var(--warning-foreground);\n  --color-chart-1: var(--chart-1);\n  --color-chart-2: var(--chart-2);\n  --color-chart-3: var(--chart-3);\n  --color-chart-4: var(--chart-4);\n  --color-chart-5: var(--chart-5);\n  /* Density: h-control, min-h-row, px-cell and p-card follow the theme's density. */\n  --spacing-control: var(--control-height);\n  --spacing-row: var(--row-height);\n  --spacing-cell: var(--cell-padding);\n  --spacing-card: var(--card-padding);\n  --shadow-card: var(--card-shadow);\n  --radius-sm: calc(var(--radius) - 4px);\n  --radius-md: calc(var(--radius) - 2px);\n  --radius-lg: var(--radius);\n  --radius-xl: calc(var(--radius) + 4px);\n}\n\n@layer base {\n  * {\n    @apply border-border;\n  }\n  body {\n    @apply bg-background text-foreground font-sans antialiased;\n  }\n}\n",
  "tsconfig.json": "{\n  \"include\": [\"**/*.ts\", \"**/*.tsx\"],\n  \"exclude\": [\"node_modules\", \"dist\"],\n  \"compilerOptions\": {\n    \"target\": \"ES2022\",\n    \"jsx\": \"react-jsx\",\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"bundler\",\n    \"paths\": { \"#/*\": [\"./src/*\"] },\n    \"lib\": [\"ES2022\", \"DOM\", \"DOM.Iterable\"],\n    \"types\": [\"vite/client\", \"node\"],\n    \"allowImportingTsExtensions\": true,\n    \"verbatimModuleSyntax\": true,\n    \"noEmit\": true,\n    \"skipLibCheck\": true,\n    \"strict\": true,\n    \"noUnusedLocals\": true,\n    \"noUnusedParameters\": true,\n    \"noFallthroughCasesInSwitch\": true\n  }\n}\n",
  "tsr.config.json": "{\n  \"routeTreeFileFooter\": [\n    \"import type { getRouter } from './router.tsx'\\nimport type { createStart } from '@tanstack/react-start'\\ndeclare module '@tanstack/react-start' {\\n  interface Register {\\n    ssr: true\\n    router: Awaited<ReturnType<typeof getRouter>>\\n  }\\n}\"\n  ]\n}\n",
  "vite.config.ts": "import tailwindcss from \"@tailwindcss/vite\";\nimport { tanstackStart } from \"@tanstack/react-start/plugin/vite\";\nimport viteReact from \"@vitejs/plugin-react\";\nimport { defineConfig } from \"vite\";\n\nexport default defineConfig({\n  resolve: { tsconfigPaths: true },\n  plugins: [tailwindcss(), tanstackStart(), viteReact()],\n});\n",
  "vitest.config.ts": "import { rmSync } from \"node:fs\";\nimport { defineConfig } from \"vitest/config\";\n\n// Tests use their own database, never the development data, and start from an empty one.\nrmSync(\"data/test\", { recursive: true, force: true });\n\nexport default defineConfig({\n  resolve: { tsconfigPaths: true },\n  test: {\n    include: [\"src/**/*.test.ts\"],\n    passWithNoTests: true,\n    env: { DATA_DIR: \"data/test\" },\n    // The test files share one database, so they run one after another.\n    fileParallelism: false,\n  },\n});\n",
};
